import {readFileSync} from 'node:fs';
import {inspectStatement} from './tools/statement-first.mjs';
const id='def-qftx-physical-bps-charge-data';
const source=readFileSync('items/'+id+'.md','utf8');
const body=source.match(/^---\n[\s\S]*?\n---\n([\s\S]*)$/)[1];
const errors=await inspectStatement(id,'definition',body);
console.log(JSON.stringify({items:[id],errors}));
process.exitCode=errors.length?1:0;
